import { Directive, ElementRef, OnInit, Renderer2, inject } from '@angular/core';

@Directive({ selector: '[qLabel]' })
export class QLabelDirective implements OnInit {
  private readonly _elementRef = inject(ElementRef);
  private readonly _renderer = inject(Renderer2);

  ngOnInit(): void {
    this._renderer.addClass(this._elementRef.nativeElement, 'q-label');
  }
}
