import { NgClass, NgSwitch, NgSwitchCase } from '@angular/common';
import {
  AfterContentInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  HostBinding,
  inject,
  Input,
  QueryList,
  ViewEncapsulation,
} from '@angular/core';
import { FormGroupDirective } from '@angular/forms';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { takeUntil } from 'rxjs/operators';
import { FormFieldControl } from './form-field-control';

@Component({
  imports: [NgClass, NgSwitch, NgSwitchCase],
  selector: 'q-form-control',
  templateUrl: './form-control.component.html',
  styleUrls: ['./form-control.component.scss'],
  providers: [QDestroyService],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QFormControlComponent implements AfterContentInit {
  @Input({ transform: booleanAttribute }) preserveFooterSpace = true;
  @Input({ transform: booleanAttribute }) showErrorIcon = true;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-form-control';

  @ContentChildren(FormFieldControl, { descendants: true })
  _formFieldControls!: QueryList<FormFieldControl>;

  @HostBinding('class') get hostClasses(): string {
    return [
      'q-form-control',
      this._isErrorState() && 'invalid',
      this.showErrorIcon && 'q-form-control-with-error-icon',
    ]
      .filter(Boolean)
      .join(' ');
  }

  private readonly _destroy$ = inject(QDestroyService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _formGroup = inject(FormGroupDirective, { optional: true });

  ngAfterContentInit(): void {
    this._handleFormControlChanges();
    this._handleFormGroupChanges();
  }

  _getDisplayedMessages(): 'error' | 'hint' {
    return this._isErrorState() ? 'error' : 'hint';
  }

  get isRadioButtonComponent(): boolean {
    return (
      (this._formFieldControls.get(0) as unknown as { dataQt: string })?.dataQt === 'q-radio-button'
    );
  }

  get isRadioGroup(): boolean {
    return (
      (this._formFieldControls.get(0) as unknown as { dataQt: string })?.dataQt === 'q-radio-group'
    );
  }

  get isCheckbox(): boolean {
    return (
      (this._formFieldControls.get(0) as unknown as { dataQt: string })?.dataQt === 'q-checkbox'
    );
  }

  private _isErrorState(): boolean {
    return (
      this._formFieldControls.some((control) => control.errorState) ||
      (!!this._formGroup?.touched && !!this._formGroup?.control?.errors)
    );
  }

  private _handleFormControlChanges(): void {
    this._formFieldControls.forEach((control) => {
      control.stateChanges.pipe(takeUntil(this._destroy$)).subscribe(() => {
        this._cdr.markForCheck();
      });

      control.ngControl?.valueChanges
        ?.pipe(takeUntil(this._destroy$))
        .subscribe(() => this._cdr.markForCheck());
    });
  }

  private _handleFormGroupChanges(): void {
    this._formGroup?.valueChanges?.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._cdr.markForCheck();
    });
  }
}
